    // --- each warp applies the reflector to its round-robin columns c>j ---
    // (tau_j already computed above, identical in every thread)
    // The panel is MIO-bound (smem throughput, 33% of stall cycles): sv[r]
    // was re-read from smem for every one of the warp's ~ib/NW columns, in
    // both the dot and the axpy. Instead, loop over r ONCE per phase, read
    // sv[r] into a register, and reuse it across all of this warp's columns
    // (acc/coef held in a tiny per-column register array). Cuts sv smem
    // reads ~ (ib/NW)x.  MAXC bounds the register array; ib/NW <= 32/8 = 4
    // for the dominant shapes, comfortably under MAXC.
    const int MAXC = 8;
    float acc[MAXC];
    int ccols[MAXC];
    int nc = 0;
    for (int c = warp; c < ib && nc < MAXC; c += NW) {
        if (c > j) { ccols[nc] = c; acc[nc] = 0.0f; ++nc; }
    }
    // dot: acc[t] = sum_r sv[r] * col_{ccols[t]}[r]
    for (int r = j + lane; r < L; r += 32) {
        float svr = sv[r];
        #pragma unroll
        for (int t = 0; t < MAXC; ++t)
            if (t < nc) acc[t] += svr * sA[(long)ccols[t] * L + r];
    }
    #pragma unroll
    for (int t = 0; t < MAXC; ++t) {
        if (t < nc) {
            float a = acc[t];
            #pragma unroll
            for (int off = 16; off > 0; off >>= 1)
                a += __shfl_xor_sync(0xffffffff, a, off);
            acc[t] = tau_j * a;                          // becomes coef
        }
    }
    // axpy: col_{ccols[t]}[r] -= coef[t] * sv[r]
    for (int r = j + lane; r < L; r += 32) {
        float svr = sv[r];
        #pragma unroll
        for (int t = 0; t < MAXC; ++t)
            if (t < nc) sA[(long)ccols[t] * L + r] -= acc[t] * svr;
    }
    __syncthreads();                                    // fence before next v write
}

